/**
 * Ready APIs, part 2: addresses that each do one job, for an app, a partner, a landing page or a
 * device: the store's hours, a shipping quote, a check of an ID, points and gift cards, shipments,
 * stock, staff attendance, tickets, polls, reviews, an app's settings… Each is under /v1/api, with
 * who may call it (anyone a few times a minute, a signed-in shopper, or a key) and its inputs' rules.
 */
import { L, apiEntry, cond, f, i, on, s, table, where, type Category, type FnIn, type GalleryEntry } from "./kit.js";

type Method = "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
type Who = "public" | "key" | "customer";
/** An address: its method and path, who may call it, and its function. */
const route = (method: Method, path: string, who: Who, fn: Omit<FnIn, "key" | "name" | "on">, more: { status?: 200 | 201 | 202 | 204; perMinute?: number; key?: string } = {}): FnIn => ({
  key: more.key ?? `${method.toLowerCase()}-${path.replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`.slice(0, 40),
  name: `${method} ${path}`,
  on: on.route(method, path, who, { ...(more.status ? { status: more.status } : {}), perMinute: more.perMinute ?? (who === "public" ? 30 : 120) }),
  ...fn,
});
const api = (key: string, category: Category, name: ReturnType<typeof L>, note: ReturnType<typeof L>, fns: FnIn[], tables: ReturnType<typeof table>[] = []) => apiEntry({ key, category, name, note, tables, fns });

